package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class LocaleUtils_toLocale_TriageGen0Test {

    @Test
    public void testToLocale_Null() {
        assertNull(LocaleUtils.toLocale(null));
    }

    @Test
    public void testToLocale_TooShort() {
        try {
            LocaleUtils.toLocale("a");
            org.junit.Assert.fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: a", e.getMessage());
        }
    }

    @Test
    public void testToLocale_InvalidFirstTwoChars() {
        try {
            LocaleUtils.toLocale("aB");
            org.junit.Assert.fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: aB", e.getMessage());
        }

        try {
            LocaleUtils.toLocale("AB");
            org.junit.Assert.fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: AB", e.getMessage());
        }
    }

    @Test
    public void testToLocale_ValidTwoChars() {
        Locale expected = new Locale("en");
        assertEquals(expected, LocaleUtils.toLocale("en"));
    }

    @Test
    public void testToLocale_InvalidLengthThreeOrFour() {
        try {
            LocaleUtils.toLocale("en_");
            org.junit.Assert.fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_", e.getMessage());
        }

        try {
            LocaleUtils.toLocale("en_a");
            org.junit.Assert.fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_a", e.getMessage());
        }
    }

    @Test
    public void testToLocale_InvalidThirdCharNotUnderscore() {
        try {
            LocaleUtils.toLocale("enaA");
            org.junit.Assert.fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: enaA", e.getMessage());
        }
    }

    @Test
    public void testToLocale_ValidWithDoubleUnderscore() {
        // Covers the case: if (ch3 == '_') return new Locale(str.substring(0, 2), "", str.substring(4));
        // Input: "en__US" -> len=6. ch0='e', ch1='n', ch2='_', ch3='_'
        Locale expected = new Locale("en", "", "US");
        assertEquals(expected, LocaleUtils.toLocale("en__US"));
    }

    @Test
    public void testToLocale_InvalidCountryCase() {
        try {
            LocaleUtils.toLocale("en_us");
            org.junit.Assert.fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_us", e.getMessage());
        }

        try {
            LocaleUtils.toLocale("en_uS");
            org.junit.Assert.fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_uS", e.getMessage());
        }
    }

    @Test
    public void testToLocale_ValidFiveChars() {
        Locale expected = new Locale("en", "US");
        assertEquals(expected, LocaleUtils.toLocale("en_US"));
    }

    @Test
    public void testToLocale_InvalidLengthSix() {
        try {
            // len is 6, but it checks len < 7 after checking ch3/ch4 uppercase
            // "en_US_" -> len 6. ch3='U', ch4='S'. len is not 5. len < 7 is true.
            LocaleUtils.toLocale("en_US_");
            org.junit.Assert.fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_US_", e.getMessage());
        }
    }

    @Test
    public void testToLocale_InvalidFifthCharNotUnderscore() {
        try {
            // len = 7. "en_USa"
            LocaleUtils.toLocale("en_USa");
            org.junit.Assert.fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            assertEquals("Invalid locale format: en_USa", e.getMessage());
        }
    }

    @Test
    public void testToLocale_ValidSevenOrMoreChars() {
        // Covers: return new Locale(str.substring(0, 2), str.substring(3, 5), str.substring(6));
        Locale expected = new Locale("en", "US", "XYZ");
        assertEquals(expected, LocaleUtils.toLocale("en_US_XYZ"));

        Locale expectedLong = new Locale("en", "US", "12345");
        assertEquals(expectedLong, LocaleUtils.toLocale("en_US_12345"));
    }
}
